// Задание 2: Сигнализация открытия двери
const int sensorPin = 6;  // Вход для датчика (геркон)
const int relayPin = 11;  // Выход для реле

void setup() {
  Serial.begin(9600);
  pinMode(sensorPin, INPUT_PULLUP); // Используем подтяжку
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
  Serial.println("Система сигнализации запущена.");
}

void loop() {
  // Чтение состояния датчика (предполагаем: HIGH - замкнут (дверь закрыта))
  int sensorState = digitalRead(sensorPin);

  if (sensorState == HIGH) {
    // Дверь закрыта
    digitalWrite(relayPin, LOW);
    Serial.println("Дверь закрыта.");
  } else {
    // Дверь открыта
    digitalWrite(relayPin, HIGH);
    Serial.println("ТРЕВОГА: Дверь открыта!");
  }

  delay(500);
}
